50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /** Minimal syntactic check for an email address: a non-empty local part, a single
68	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    /** Dedicated audit logger; emits an audit line on successful owner create. */
73	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    private final TelephoneNormalizer telephoneNormalizer;
84	
85	    private final AddressNormalizer addressNormalizer;
86	
87	    public OwnerRestControllerV1(ClinicService clinicService,
88	                                 OwnerMapper ownerMapper,
89	                                 PetMapper petMapper,
90	                                 VisitMapper visitMapper,
91	                                 TelephoneNormalizer telephoneNormalizer,
92	                                 AddressNormalizer addressNormalizer) {
93	        this.clinicService = clinicService;
94	        this.ownerMapper = ownerMapper;
95	        this.petMapper = petMapper;
96	        this.visitMapper = visitMapper;
97	        this.telephoneNormalizer = telephoneNormalizer;
98	        this.addressNormalizer = addressNormalizer;
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
104	        Collection<Owner> owners;
105	        if (lastName != null) {
106	            owners = this.clinicService.findOwnerByLastName(lastName);
107	        } else {
108	            owners = this.clinicService.findAllOwners();
109	        }
110	        if (owners.isEmpty()) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
119	        Owner owner = this.clinicService.findOwnerById(ownerId);
120	        if (owner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        HttpHeaders headers = new HttpHeaders();
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	        if (owner.getRegistrationDate() == null) {
132	            owner.setRegistrationDate(LocalDate.now());
133	        }
134	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
135	        LocalDate registrationDate = owner.getRegistrationDate();
136	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
137	            .map(Owner::getRegistrationDate)
138	            .filter(registrationDate::equals)
139	            .count();
140	        if (ownersCreatedThatDay >= 100) {
141	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
142	        }
143	        String address = addressNormalizer.normalize(owner.getAddress());
144	        if (address.isBlank()) {
145	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
146	        }
147	        owner.setAddress(address);
148	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
149	        if (telephone == null) {
150	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
151	        }
152	        owner.setTelephone(telephone);
153	        String email = owner.getEmail();
154	        if (email != null) {
155	            email = email.trim();
156	            if (!EMAIL_PATTERN.matcher(email).matches()) {
157	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
158	            }
159	            owner.setEmail(email.toLowerCase(Locale.ROOT));
160	        }
161	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
162	            .map(Owner::getTelephone)
163	            .filter(Objects::nonNull)
164	            .map(telephoneNormalizer::normalize)
165	            .anyMatch(telephone::equals);
166	        if (telephoneInUse) {
167	            return new ResponseEntity<>(HttpStatus.CONFLICT);
168	        }
169	        String cityKey = normalizeIdentity(owner.getCity());
170	        long ownersInCity = this.clinicService.findAllOwners().stream()
171	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
172	            .count();
173	        if (ownersInCity >= 50) {
174	            return new ResponseEntity<>(HttpStatus.CONFLICT);
175	        }
176	        String lastNameKey = normalizeIdentity(owner.getLastName());
177	        String addressKey = addressNormalizer.normalize(owner.getAddress());
178	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
179	            boolean householdDuplicate = this.clinicService.findAllOwners().stream()
180	                .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
181	                    && addressNormalizer.normalize(existing.getAddress()).equals(addressKey));
182	            if (householdDuplicate) {
183	                return new ResponseEntity<>(HttpStatus.CONFLICT);
184	            }
185	        }
186	        owner.setHouseholdId(householdId(lastNameKey, addressKey));
187	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
188	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
189	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
190	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
191	            .count();
192	        owner.setNamesakeCount(namesakeCount);
193	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
194	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
195	        this.clinicService.saveOwner(owner);
196	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
197	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
198	            ownerMapper.membershipLevel(owner));
199	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
200	        headers.setLocation(UriComponentsBuilder.newInstance()
201	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
202	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
203	    }
204	
205	    /**
206	     * Normalize a value for household-identity comparison: null becomes an empty
207	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
208	     * to a single space, and the result is lower-cased.
209	     */
210	    private static String normalizeIdentity(String value) {
211	        if (value == null) {
212	            return "";
213	        }
214	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
215	    }
216	
217	    /**
218	     * Build the stable, shared household identifier for an owner, formatted
219	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
220	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
221	     * Owners in the same household (same normalized lastName and address) therefore
222	     * derive an identical householdId.
223	     */
224	    private static String householdId(String lastNameKey, String addressKey) {
225	        String source = lastNameKey + "|" + addressKey;
226	        try {
227	            byte[] digest = MessageDigest.getInstance("SHA-256")
228	                .digest(source.getBytes(StandardCharsets.UTF_8));
229	            StringBuilder sb = new StringBuilder(digest.length * 2);
230	            for (byte b : digest) {
231	                sb.append(String.format("%02x", b));
232	            }
233	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
234	        }
235	        catch (NoSuchAlgorithmException e) {
236	            throw new IllegalStateException("SHA-256 not available", e);
237	        }
238	    }
239	
240	    /**
241	     * Build the customer code assigned on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}:
242	     * CITY3 is the upper-cased first three letters of {@code city}, LAST3 is the upper-cased
243	     * first three letters of {@code lastName} and NNNN is a per-city 4-digit zero-padded
244	     * sequence equal to one more than the number of owners already in that city
245	     * (e.g. 'LON-SMI-0007').
246	     */
247	    private String nextCustomerCode(String city, String lastName) {
248	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
249	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
250	        String cityKey = normalizeIdentity(city);
251	        int sequence = (int) this.clinicService.findAllOwners().stream()
252	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
253	            .count() + 1;
254	        return String.format("%s-%s-%04d", city3, last3, sequence);
255	    }
256	
257	    /**
258	     * Roll a registration date forward to the next business day: a Saturday or Sunday
259	     * advances to the following Monday, and a weekday is returned unchanged.
260	     */
261	    private static LocalDate toBusinessDay(LocalDate date) {
262	        return switch (date.getDayOfWeek()) {
263	            case SATURDAY -> date.plusDays(2);
264	            case SUNDAY -> date.plusDays(1);
265	            default -> date;
266	        };
267	    }
268	
269	    /**
270	     * Build the membership number assigned on create, formatted
271	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
272	     * {@code registrationDate} year (e.g. 'LON-SMI-0007-M26').
273	     */
274	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
275	        String yy = String.format("%02d", registrationDate.getYear() % 100);
276	        return customerCode + "-M" + yy;
277	    }
278	
279	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
280	    @Override
281	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
282	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
283	        if (currentOwner == null) {
284	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
285	        }
286	        currentOwner.setAddress(ownerFieldsDto.getAddress());
287	        currentOwner.setCity(ownerFieldsDto.getCity());
288	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
289	        currentOwner.setLastName(ownerFieldsDto.getLastName());
290	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
291	        this.clinicService.saveOwner(currentOwner);
292	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
293	    }
294	
295	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
296	    @Transactional
297	    @Override
298	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
299	        Owner owner = this.clinicService.findOwnerById(ownerId);
300	        if (owner == null) {
301	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
302	        }
303	        this.clinicService.deleteOwner(owner);
304	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
305	    }
306	
307	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
308	    @Override
309	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
310	        Owner owner = this.clinicService.findOwnerById(ownerId);
311	        if (owner == null) {
312	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
313	        }
314	        HttpHeaders headers = new HttpHeaders();
315	        Pet pet = petMapper.toPet(petFieldsDto);
316	        owner.setId(ownerId);
317	        pet.setOwner(owner);
318	        pet.getType().setName(null);
319	        this.clinicService.savePet(pet);
320	        PetDto petDto = petMapper.toPetDto(pet);
321	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
322	            .buildAndExpand(pet.getId()).toUri());
323	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
324	    }
325	
326	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
327	    @Override
328	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
329	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
330	        if (currentOwner != null) {
331	            Pet currentPet = this.clinicService.findPetById(petId);
332	            if (currentPet != null) {
333	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
334	                currentPet.setName(petFieldsDto.getName());
335	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
336	                this.clinicService.savePet(currentPet);
337	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
338	            }
339	        }
340	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
341	    }
342	
343	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
344	    @Override
345	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
346	        HttpHeaders headers = new HttpHeaders();
347	        Visit visit = visitMapper.toVisit(visitFieldsDto);
348	        Pet pet = new Pet();
349	        pet.setId(petId);
350	        visit.setPet(pet);
351	        this.clinicService.saveVisit(visit);
352	        VisitDto visitDto = visitMapper.toVisitDto(visit);
353	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
354	            .buildAndExpand(visit.getId()).toUri());
355	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
356	    }
357	
358	
359	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
360	    @Override
361	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
362	        Owner owner = this.clinicService.findOwnerById(ownerId);
363	        if (owner != null) {
364	            Pet pet = owner.getPet(petId);
365	            if (pet != null) {
366	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
367	            }
368	        }
369	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
370	    }
371	}
